package cn.zhuatech.itsm.deep;import cn.zhuatech.itsm.common.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/itsm-ops") @PreAuthorize("hasRole('ADMIN')") public class DeepItsmAdminController{private final DeepItsmService s;public DeepItsmAdminController(DeepItsmService x){s=x;}@PostMapping("/cis")ApiResponse<?> ci(@RequestBody DeepItsmService.CiInput x){return ApiResponse.ok(s.createCi(x));}@PostMapping("/cis/{id}/activate")ApiResponse<?> activate(@PathVariable Long id){return ApiResponse.ok(s.activateCi(id));}@PostMapping("/problems/{id}/close")ApiResponse<?> problem(@PathVariable Long id){return ApiResponse.ok(s.closeProblem(id));}@PostMapping("/changes/{id}/approve")ApiResponse<?> approve(@PathVariable Long id,@RequestBody DeepItsmService.ApprovalInput x){return ApiResponse.ok(s.approveChange(id,x));}@PostMapping("/changes/{id}/implement")ApiResponse<?> implement(@PathVariable Long id,@RequestBody DeepItsmService.EvidenceInput x){return ApiResponse.ok(s.implement(id,x));}@PostMapping("/changes/{id}/close")ApiResponse<?> close(@PathVariable Long id){return ApiResponse.ok(s.closeChange(id));}}
